-- Blog & Promo Posts
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-001', 'Grand Opening Siap Nyafe Coffee', 'grand-opening-siap-nyafe-coffee-2', 'Kami dengan bangga mengumumkan pembukaan Siap Nyafe Coffee di pusat kota Jakarta. Hadir dengan konsep modern industrial yang nyaman, kami menyajikan berbagai pilihan kopi berkualitas dari biji kopi pilihan petani lokal Indonesia. Mulai dari espresso klasik hingga minuman kopi kekinian seperti Kopi Susu Gula Aren dan Cold Brew. Dukung terus kopi lokal Indonesia!', 'Akhirnya Siap Nyafe Coffee resmi hadir di Jakarta!', 'NEWS', 'PUBLISHED', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=800&auto=format&fit=crop&q=80', '2026-06-15T08:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-002', 'Welcome to the Family: Our Story', 'welcome-to-the-family-our-story-3', 'Berawal dari kecintaan terhadap kopi Nusantara, kami mendirikan Siap Nyafe Coffee dengan misi memperkenalkan cita rasa kopi Indonesia ke seluruh dunia. Setiap cangkir yang kami sajikan adalah hasil seleksi ketat dari petani kopi terbaik di Sumatera, Jawa, Bali, dan Sulawesi. Kami percaya bahwa secangkir kopi yang baik bisa membawa kebahagiaan dan menyatukan orang-orang.', 'Cerita di balik lahirnya Siap Nyafe Coffee.', 'NEWS', 'PUBLISHED', 'https://images.unsplash.com/photo-1442512595331-e89e73853f31?w=800&auto=format&fit=crop&q=80', '2026-06-15T09:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-003', 'Meet Our Barista Team', 'meet-our-barista-team-4', 'Tim barista kami adalah para profesional yang telah terlatih dan bersertifikat. Mereka tidak hanya ahli dalam meracik kopi, tetapi juga passionate dalam memberikan pengalaman terbaik bagi setiap pelanggan. Dari latte art yang indah hingga rekomendasi kopi yang tepat sesuai selera Anda, barista kami siap melayani.', 'Kenalan dengan para barista handal Siap Nyafe.', 'NEWS', 'PUBLISHED', 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=800&auto=format&fit=crop&q=80', '2026-06-20T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-004', 'The Art of Latte Art', 'the-art-of-latte-art-5', 'Latte art bukan sekadar hiasan di atas kopi, tetapi sebuah bentuk seni yang membutuhkan keahlian dan latihan. Barista kami telah menguasai berbagai teknik pouring untuk menciptakan rosetta, tulip, swan, dan berbagai motif lainnya. Setiap cangkir latte art adalah karya seni yang unik untuk Anda!', 'Belajar seni latte art dari barista profesional.', 'NEWS', 'PUBLISHED', 'https://images.unsplash.com/photo-1534778101976-62847782c213?w=800&auto=format&fit=crop&q=80', '2026-06-25T11:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-005', 'Kopi Indonesia: Dari Petani ke Cangkir', 'kopi-indonesia-dari-petani-ke-cangkir-6', 'Indonesia adalah salah satu penghasil kopi terbaik di dunia. Kopi Gayo dari Aceh dengan karakter earthy dan spicy, Kopi Java dengan body yang smooth dan hints of chocolate, serta Kopi Toraja dengan kompleksitas rasa yang kaya. Di Siap Nyafe, kami bangga menyajikan kopi-kopi terbaik Nusantara dengan metode seduh yang tepat.', 'Perjalanan biji kopi dari kebun hingga ke cangkir Anda.', 'NEWS', 'PUBLISHED', 'https://images.unsplash.com/photo-1524350876685-274059332603?w=800&auto=format&fit=crop&q=80', '2026-07-01T08:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-006', 'New Cold Brew Arrival', 'new-cold-brew-arrival-7', 'Kami menghadirkan Cold Brew baru yang diseduh selama 12 jam untuk menghasilkan rasa yang lebih smooth, rendah asam, dan full-bodied. Tersedia juga Nitro Cold Brew dengan tekstur creamy berkat infus nitrogen. Nikmati kesegaran Cold Brew di hari yang panas!', 'Cold brew baru dengan rasa lebih smooth!', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=800&auto=format&fit=crop&q=80', '2026-07-05T09:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-007', 'Buy 1 Get 1 Every Monday', 'buy-1-get-1-every-monday-8', 'Setiap hari Senin, kami memberikan promo spesial Buy 1 Get 1 untuk semua menu minuman. Ajak teman atau kolega Anda dan nikmati kopi favorit berdua dengan harga yang lebih hemat. Promo berlaku sepanjang hari untuk dine-in maupun takeaway. Syarat dan ketentuan berlaku.', 'Senin ceria dengan promo Buy 1 Get 1 untuk semua minuman.', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1511920170033-f8396924c348?w=800&auto=format&fit=crop&q=80', '2026-07-10T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-008', 'Happy Hour 3-5 PM', 'happy-hour-3-5-pm-9', 'Butuh penyemangat di sore hari? Nikmati Happy Hour setiap hari pukul 15.00 - 17.00 dengan diskon 20% untuk semua menu minuman. Cocok untuk melepas penat setelah seharian beraktivitas. Jangan lewatkan promo spesial ini!', 'Diskon 20% untuk semua menu setiap jam 3-5 sore!', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1497636577773-f1231844b336?w=800&auto=format&fit=crop&q=80', '2026-07-12T14:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-009', 'Weekly Special: New Menu Launch', 'weekly-special-new-menu-launch-10', 'Setiap minggu kami menghadirkan menu spesial baru yang siap memanjakan lidah Anda. Mulai dari minuman seasonal hingga makanan ringan pendamping kopi. Follow Instagram kami untuk update menu spesial minggu ini!', 'Coba menu-menu baru kami yang lebih variatif!', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1498804103079-a6351b050096?w=800&auto=format&fit=crop&q=80', '2026-07-15T08:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-010', 'Student Discount 15%', 'student-discount-15--11', 'Tunjukkan kartu pelajar atau mahasiswa Anda dan dapatkan diskon 15% untuk semua pembelian. Kami ingin mendukung generasi muda Indonesia untuk lebih produktif dengan secangkir kopi berkualitas. Promo berlaku setiap hari selama jam operasional.', 'Pelajar dan mahasiswa dapat diskon 15% setiap hari.', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1521017432531-fbd92d768814?w=800&auto=format&fit=crop&q=80', '2026-07-18T09:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-011', 'New Menu: Healthy Options', 'new-menu-healthy-options-12', 'Kini hadir pilihan menu sehat untuk Anda yang peduli dengan kesehatan. Smoothie bowl dengan buah segar, oatmeal latte, serta minuman rendah kalori. Nikmati kopi favorit Anda tanpa rasa bersalah! Tersedia juga opsi susu alternatif seperti oat milk, almond milk, dan soy milk.', 'Menu sehat baru untuk gaya hidup sadar kesehatan.', 'PROMO', 'PUBLISHED', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800&auto=format&fit=crop&q=80', '2026-07-20T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-012', 'Live Music Every Friday', 'live-music-every-friday-13', 'Setiap hari Jumat pukul 19.00 - 21.00, kami menghadirkan live music dengan berbagai genre musik akustik. Nikmati kopi favorit Anda ditemani alunan musik yang menenangkan. Bawa teman dan keluarga untuk pengalaman ngopi yang lebih berkesan!', 'Nikmati live music setiap Jumat malam di Siap Nyafe.', 'EVENT', 'PUBLISHED', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=800&auto=format&fit=crop&q=80', '2026-06-18T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-013', 'Coffee Brewing Workshop', 'coffee-brewing-workshop-14', 'Ikuti workshop brewing kopi kami setiap hari Sabtu pukul 10.00 - 12.00. Pelajari berbagai metode brewing mulai dari V60, Aeropress, French Press, hingga Cold Brew. Cocok untuk pemula hingga enthusiast yang ingin memperdalam ilmu kopi. Biaya pendaftaran Rp 100.000 termasuk alat dan bahan.', 'Belajar teknik brewing kopi yang benar.', 'EVENT', 'PUBLISHED', 'https://images.unsplash.com/photo-1507133750040-4a8f57021571?w=800&auto=format&fit=crop&q=80', '2026-06-22T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-014', 'Open Mic Night', 'open-mic-night-15', 'Setiap hari Rabu malam, Siap Nyafe menjadi tempat bagi para kreator untuk mengekspresikan diri melalui open mic. Puisi, komedi, musik, storytelling — semua boleh tampil! Daftarkan diri Anda di kasir atau melalui Instagram kami. Tiket masuk gratis dengan minimum pemesanan satu minuman.', 'Tunjukkan bakat Anda di panggung open mic!', 'EVENT', 'PUBLISHED', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=800&auto=format&fit=crop&q=80', '2026-07-08T10:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-015', 'Year-End Celebration', 'year-end-celebration-16', 'Mari rayakan akhir tahun bersama Siap Nyafe Coffee! Akan ada live music spesial, games berhadiah, dan menu spesial akhir tahun. Datang dan nikmati momen kebersamaan di penghujung tahun. Reserve tempat Anda sekarang karena kapasitas terbatas!', 'Rayakan akhir tahun bersama Siap Nyafe!', 'EVENT', 'PUBLISHED', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&auto=format&fit=crop&q=80', '2026-07-15T12:00');
INSERT OR IGNORE INTO posts (id, title, slug, content, excerpt, category, status, featuredImage, publishedAt) VALUES ('post-016', 'Barista Competition 2026', 'barista-competition-2026-17', 'Siap Nyafe menjadi tuan rumah kompetisi barista antar kafe se-Jakarta. Adu skill latte art, brewing, dan speed challenge Anda. Hadiah utamaRp 5.000.000 + trophy. Pendaftaran dibuka sampai 31 Juli 2026. Hubungi kami untuk informasi lebih lanjut.', 'Ikuti kompetisi barista antar kafe se-Jakarta!', 'EVENT', 'PUBLISHED', 'https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=800&auto=format&fit=crop&q=80', '2026-07-18T10:00');

